function validate([s, k, fill]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses lowercase letters only.';
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is between 1 and 100.';
  if (typeof fill !== 'string' || !/^[a-z]$/.test(fill)) return 'fill is a single lowercase letter.';
  return null;
}

