function divideString(s, k, fill) {
  const total = Math.ceil(s.length / k) * k;
  const chars = s.split('');
  while (chars.length < total) chars.push(fill);
  const result = [];
  let current = '';
  for (const c of chars) {
    current += c;
    if (current.length === k) { result.push(current); current = ''; }
  }
  return result;
}

