function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alpha = size === 'large' ? 26 : 1 + Math.floor(rand() * 4);
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 12);
  const k = size === 'large' ? 1 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 14);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[Math.floor(rand() * alpha)];
  const fill = letters[Math.floor(rand() * 26)];
  return [s, k, fill];
}
